// helpers to check for hip errors
#define HIP_CHECK(ans) {\
    gpuAssert((ans), __FILE__, __LINE__);\
  }\

static inline void gpuAssert(hipError_t code, const char *file, int line) {
  if (code != hipSuccess) {
    const char *prefix = "Triton Error [HIP]: ";
    const char *str = nullptr;
    hipError_t error_status = hipDrvGetErrorString(code, &str);
    if (error_status != hipSuccess || str == nullptr) {
        str = "HIP error text unavailable";
    }
    char err[1024] = {0};
    strcat(err, prefix);
    strcat(err, str);
    printf("%s\\n", err);
    exit(code);
  }
}

